// Global Key Press Flag
volatile int key01_pressed = 0;

float string_frequencies[6] = {82.41, 110.00, 146.83, 196.00, 246.94, 329.63};	// EADGBe
volatile int string_index = 0;
volatile float phase = 0.0f;
float displayed_frequency = 0.0f;
float last_valid_frequency = 0.0f;
int hold_frames = 0;
int sample_buffer[SAMPLE_BUFFER_SIZE];
int sample_buffer_index = 0;
float last_theta = 0.0f;

// Arrow Positions
int arrow_x_positions[NUM_POSITIONS] = {55, 85, 120, 160, 195, 225};
int arrow_y_positions[NUM_POSITIONS] = {150, 150, 150, 150, 150, 150};

// Memory Mapped IO Registers
volatile int *audio_control = (int *)0xFF203040;
volatile int *audio_fifospace = (int *)0xFF203044;
volatile int *audio_leftdata = (int *)0xFF203048;
volatile int *audio_rightdata = (int *)0xFF20304C;
volatile int *key_ptr = (int *)0xFF200050;
volatile int *hex_3to0 = (int *)0xFF200020;
volatile int *hex_5to4 = (int *)0xFF200030;

// HEX Codes (Active high)
int hex_codes[10] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F  // 9
};

// Mode Selection
typedef enum {
    MODE_GENERATOR,
    MODE_DETECTOR
} Mode;

volatile Mode current_mode = MODE_DETECTOR;		// Boots into DETECTOR by default

int main (void) {
	
	// Interrupt Setup 
	set_KEY(); 
	set_interrupts();
	
	while (1){
		if (current_mode == MODE_DETECTOR){	
			RUN_DETECTOR();	
		}
		else if (current_mode == MODE_GENERATOR){
			RUN_GENERATOR();
		}
	}
}	


void RUN_GENERATOR(void){
	
	int signal = 0;	

	draw_generator_bg();
	draw_arrow(arrow_x_positions[string_index], arrow_y_positions[string_index]);

	while (1) {
		
		// Check if mode has been changed, if so, return to main
		if (current_mode != MODE_GENERATOR){
			break;
		}
		
		int fifospace = *audio_fifospace;
		
		int WSRC = (fifospace >> 16) & 0xFF; 
		int WSLC = (fifospace >> 24) & 0xFF; 
		
		float freq = string_frequencies[string_index];
		float phase_increment = (TABLE_SIZE * freq) / Fs;		// each sample 
		
		if ( WSRC > 0 && WSLC > 0){ // have space to store it in
			
			int index = (int) phase;		// type cast to integer -- truncate decimal to obtain look up table index value
			signal = (int)(sine_table[index]);
			
			*audio_leftdata = signal;	// write and push into output FIFO
			*audio_rightdata = signal;
		
			phase = phase + phase_increment;	// increment phase for next digital sample 
			if (phase >= TABLE_SIZE){			// phase exceed 1 period
				phase = phase - TABLE_SIZE;		// then start back from 0
			}
		}
		
		if (key01_pressed) {
			draw_generator_bg();
			draw_arrow(arrow_x_positions[string_index], arrow_y_positions[string_index]);
			key01_pressed = 0;
		}
		
	}
}

void RUN_DETECTOR(void) {
    int cx = 160;
    int cy = 185;
    int length = 60;
    int last_string = -1;

    draw_detection_bg();

    while (1) {
        if (current_mode != MODE_DETECTOR) {
            break;
        }
        int fifospace = *audio_fifospace;
        int RARC = fifospace & 0xFF;
        int RALC = (fifospace >> 8) & 0xFF;

        if (RARC > 0 && RALC > 0) {
            int leftdata = *audio_leftdata;
            int rightdata = *audio_rightdata;
            sample_buffer[sample_buffer_index] = (leftdata + rightdata)/2;  // store average of left and right popped sample into buffer
            sample_buffer_index++;

            if (sample_buffer_index >= SAMPLE_BUFFER_SIZE) {    // buffer is filled -- can process
                sample_buffer_index = 0; 

                long long mean = 0;
                int centered_buffer[SAMPLE_BUFFER_SIZE];

                for (int i = 0; i < SAMPLE_BUFFER_SIZE; i++) {  // remove DC offset 
                    mean += sample_buffer[i];
                }
                mean = mean / SAMPLE_BUFFER_SIZE;

                for (int i = 0; i < SAMPLE_BUFFER_SIZE; i++) {
                    centered_buffer[i] = sample_buffer[i] - (int)mean;
                }

                float filtered_buffer[SAMPLE_BUFFER_SIZE];
                float lp_prev = (float)centered_buffer[0];
                float hp_prev = 0.0f;
                float x_prev  = lp_prev;

                filtered_buffer[0] = 0.0f;
                
                // filtering -- cascaded lowpass + highpass
                for (int i = 1; i < SAMPLE_BUFFER_SIZE; i++) {
                    float x = (float)centered_buffer[i];

                    // lowpass -- cutoff ~ 366 Hz
                    float a_lp = 0.25f;
                    float lp = lp_prev + a_lp * (x - lp_prev);  // last output + fraction of new input -- supress fast changes

                    // highpass -- cutofff ~ 65 Hz
                    float a_hp = 0.95f;
                    float hp = a_hp * (hp_prev + lp - x_prev);  // if lp ~ x_prev, hp is small - highpass

                    filtered_buffer[i] = hp;

                    lp_prev = lp;
                    hp_prev = hp;
                    x_prev = lp;
                }

                // energy gate -- skip frames that are too quiet
                long long energy = 0;
                for (int i = 0; i < SAMPLE_BUFFER_SIZE; i++) {
                    long long x = filtered_buffer[i];
                    energy += x * x;
                }

                int valid_pitch = 0;
                float measured_frequency = 0.0f;

                if (energy > 1500000000LL) {   // can tune if needed
                    int min_shift = 20;
                    int max_shift = 100;

                    // YIN algorithm
                    long long d[101]; 
                    float dprime[101];

                    for (int shift = 0; shift <= max_shift; shift++) {
                        d[shift] = 0;
                        dprime[shift] = 1.0f;
                    }

                    // Raw difference function (d)
                    for (int shift = min_shift; shift <= max_shift; shift++) {
                        long long diff_sum = 0;

                        for (int j = 0; j < SAMPLE_BUFFER_SIZE - shift; j++) {
                            long long diff = (long long)filtered_buffer[j] - filtered_buffer[j + shift];
                            diff_sum += diff * diff;
                        }

                        d[shift] = diff_sum;
                    }

                    // Cumulative mean normalized difference
                    dprime[0] = 1.0f;
                    long long running_sum = 0;

                    for (int shift = 1; shift <= max_shift; shift++) {
                        if (shift < min_shift) {
                            dprime[shift] = 1.0f;
                        } else {
                            running_sum += d[shift];

                            if (running_sum == 0) {
                                dprime[shift] = 1.0f;
                            } else {
                                float average = (float)running_sum / (float)shift;
                                dprime[shift] = (float)d[shift] / average;
                            }
                        }
                    }

                    // Find first dip below threshold
                    float threshold = 0.40f;        // can tune
                    int best_phaseshift = -1;

                    for (int shift = min_shift; shift < max_shift; shift++) {
                        if (dprime[shift] < threshold) {
                            while ((shift + 1 <= max_shift) &&
                                   (dprime[shift + 1] < dprime[shift])) {
                                shift++;
                            }
                            best_phaseshift = shift;            // accept first shift that satisfies threshold
                            break;
                        }
                    }
                    
                    // Interpolation -- Quadratic fit
                    if (best_phaseshift != -1 && best_phaseshift > min_shift && best_phaseshift < max_shift) {

                        float left = dprime[best_phaseshift - 1];
                        float center = dprime[best_phaseshift];
                        float right = dprime[best_phaseshift + 1];

                        float delta = 0.0f;
                        float denominator = left - 2.0f * center + right;

                        if (denominator != 0.0f) {
                            delta = 0.5f * (left - right) / denominator;
                        }

                        float interpolated_phaseshift =
                            (float)best_phaseshift + delta;

                        if (interpolated_phaseshift > 0.0f) {
                            measured_frequency = (float)Fs / interpolated_phaseshift;

                            // Octave correction -- compare measured frequency with half and double frequencies to closest string
                            float f0 = measured_frequency;
                            float f_half = 0.5f * f0;
                            float f_double = 2.0f * f0;

                            int idx0 = find_closest_string(f0);
                            int idxh = find_closest_string(f_half);
                            int idxd = find_closest_string(f_double);

                            float err0 = fabsf(f0 - string_frequencies[idx0]);
                            float errh = fabsf(f_half - string_frequencies[idxh]);
                            float errd = fabsf(f_double - string_frequencies[idxd]);

                            float best_freq = f0;
                            float best_err = err0;

                            // only switch if octave corrected option is a lot better
                            if (f_half >= 70.0f && errh < 0.7f * best_err && f0 >= 200.0f) {    // tunable error values
                                best_freq = f_half;
                                best_err = errh;
                            }
                            if (f_double <= 400.0f && errd < 0.7f * best_err && f0 <= 180.0f && f0 >= 150.0f) {
                                best_freq = f_double;
                                best_err = errd;
                            }

                            measured_frequency = best_freq;

                            // double check
                            if (measured_frequency >= 70.0f && measured_frequency <= 400.0f) {
                                valid_pitch = 1;
                            }
                        }
                    }
                }

                // Update held pitch only if this frame is valid
                if (valid_pitch) {
                    last_valid_frequency = measured_frequency;
                    hold_frames = 2;    // for smoothing
                } else {
                    if (hold_frames > 0) {
                        hold_frames--;
                    }
                }

                // Pick display target to approach (smoothing)
                float target_frequency = last_valid_frequency;

                if (valid_pitch || hold_frames > 0) {
                    if (displayed_frequency == 0.0f) {  // if it was a blank screen
                        displayed_frequency = target_frequency;
                    } else {
                        float alpha = 0.60f;
                        displayed_frequency += alpha * (target_frequency - displayed_frequency);   // slowly approach target frequency
                    }

                    int display_frequency = (int)(displayed_frequency + 0.5f);  // rounded for hex display
                    if (display_frequency < 0) display_frequency = 0;   // 3 digit hex
                    if (display_frequency > 999) display_frequency = 999;

                    int ones_digit = hex_codes[display_frequency % 10];
                    int tens_digit = hex_codes[(display_frequency / 10) % 10];
                    int hundreds_digit = hex_codes[(display_frequency / 100) % 10];

                    *hex_3to0 = (hundreds_digit << 16) | (tens_digit << 8) | ones_digit;
                } else {
                    // no valid pitch -- blank hex
                    displayed_frequency = 0.0f;
                    *hex_3to0 = 0x0;
                }
            }
            if (displayed_frequency > 0.0f) {   // only update dial when valid pitch (displayed_frequency > 0.0f)
                int closest_string = find_closest_string(displayed_frequency);
                float target_freq = string_frequencies[closest_string];
                
                float theta = freq_to_angle(displayed_frequency, target_freq);
        
                if (closest_string == 0) draw_E();
                else if (closest_string == 1) draw_A();
                else if (closest_string == 2) draw_D();
                else if (closest_string == 3) draw_G();
                else if (closest_string == 4) draw_B();
                else if (closest_string == 5) draw_highE();

                if (last_theta != theta || last_string != closest_string) {
                    draw_detection_bg();
                    draw_needle(cx, cy, length, theta, 0xFFFF);
                }
                last_string = closest_string;
                last_theta = theta;
            }
            
        }

       
    }
}

