int find_closest_string(float measured_freq) {
	int best_index = 0;
	float best_diff = fabs(measured_freq - string_frequencies[0]);
	
	for (int i = 1; i < 6; i++) {
		float diff = fabs(measured_freq - string_frequencies[i]);
		if (diff < best_diff) {
			best_diff = diff;
			best_index = i;
		}
	}
	
	return best_index;
}

static void handler(void) {
	
	int mcause_value;
    __asm__ volatile ("csrr %0, mcause" : "=r"(mcause_value));		// read mcause

    if (mcause_value == 0x80000012) {   // KEY interrupt with bit 31 on
    	KEY_ISR();
    }
}


void set_KEY(void) {
    *(key_ptr + 3) = 0xF;   // clear EdgeCapture register
    *(key_ptr + 2) = 0xF;   // enable interrupt for all keys
}

void set_interrupts(void){
	int mstatus_value, mtvec_value, mie_value;

	mstatus_value = 0b1000;			// interrupt bit mask
	__asm__ volatile ("csrc mstatus, %0" :: "r"(mstatus_value)); // disable global interrupts

	mtvec_value = (int) &handler; 	// address of main ISR
	__asm__ volatile ("csrw mtvec, %0" :: "r"(mtvec_value));	// put it into mtvec

	__asm__ volatile ("csrr %0, mie" : "=r"(mie_value));		// read current mie register
	__asm__ volatile ("csrc mie, %0" :: "r"(mie_value));		// clear current mie register
	mie_value = 0x40000;		// 0x40000 = bit 18 on for KEY
	__asm__ volatile ("csrs mie, %0" :: "r"(mie_value));	// store into mie register

	__asm__ volatile ("csrs mstatus, %0" :: "r"(mstatus_value)); // re-enable global interrupt bit
}

void KEY_ISR(void) {
	
	int pressed; 
	pressed = *(key_ptr + 3); // read edge capture register
	*(key_ptr + 3) = pressed; // clear edge capture register
	
	if (pressed & 0b0001) {        // KEY0 WAS PRESSED
        key01_pressed = 1;			// set global flag to 1
		
		string_index = (string_index + 1) % 6;
		
		// clear write 
		int status = *audio_control;
		*audio_control = status | 0x8;      // set CW = 1, clear output FIFOs
		*audio_control = status & ~0x8;     // set CW = 0 (pulse CW to clear, have to set back to 0)
		phase = 0.0f;			// reset phase
    }
	else if (pressed & 0b0010){
		key01_pressed = 1;
		
		string_index--;
		if (string_index < 0) string_index = 5;
		
		// clear write 
		int status = *audio_control;
		*audio_control = status | 0x8;      // set CW = 1, clear output FIFOs
		*audio_control = status & ~0x8;     // set CW = 0 (pulse CW to clear, have to set back to 0)
		phase = 0.0f;			// reset phase
		
	}
	else if (pressed & 0b0100){ 		// KEY2 WAS PRESSED 
		if (current_mode == MODE_DETECTOR){
			current_mode = MODE_GENERATOR;
		}
	}
	else if (pressed & 0b1000){			// KEY3 WAS PRESSED
		if (current_mode == MODE_GENERATOR){
			current_mode = MODE_DETECTOR;
			int status = *audio_control;
			
			// Clear output FIFOs
			*audio_control = status | 0x8;      
			*audio_control = status & ~0x8;     
		}
	}
}

void plot_pixel(int x, int y, short int color) {
	// address = base + y * 1024 + x * 2
    volatile short int *addr = (volatile short int *)(VGA_PIXEL_BUF + (y << 10) + (x << 1)); // each pixel is 2 bytes wide
    *addr = color; // put color into calculated (x,y)
}

void draw_arrow(int arrow_x, int arrow_y) {
    for (int local_y = 0; local_y < SYMBOL_HEIGHT; local_y++) {
        for (int local_x = 0; local_x < SYMBOL_WIDTH; local_x++) {
            short int color_arrow =
                tuner_arrow[local_y * SYMBOL_WIDTH + local_x];

            if (color_arrow != 0x0000) {
                plot_pixel(arrow_x + local_x, arrow_y + local_y, color_arrow);
            }
        }
    }
}

void draw_detection_bg() {
	for (int y = 0; y < SCREEN_HEIGHT; y++) {
		for (int x = 0; x < SCREEN_WIDTH; x++) {
			short int color = pitch_detection[y * SCREEN_WIDTH + x];
			plot_pixel(x,y,color);
		}
	}
}

void draw_generator_bg() {
    for (int y = 0; y < SCREEN_HEIGHT; y++) {
        for (int x = 0; x < SCREEN_WIDTH; x++) {

            short int color = tone_generator[y * SCREEN_WIDTH + x];
            plot_pixel(x, y, color);
		}
    }
}

void clear_screen(){

	for (int i = 0; i < 320; i++){		// loop over x coordinates
		for (int j = 0; j < 240; j++){	// loop over y coordinates
			plot_pixel(i, j, 0x0000);	// clear them all - make them black
		}
	}
}

void draw_line(int x0, int y0, int x1, int y1, short int line_color) {
     int is_steep = abs(y1 - y0) > abs(x1 - x0);

    if (is_steep) {
        int temp;
        temp = x0; x0 = y0; y0 = temp;
        temp = x1; x1 = y1; y1 = temp;
    }

    if (x0 > x1) {
        int temp;
        temp = x0; x0 = x1; x1 = temp;
        temp = y0; y0 = y1; y1 = temp;
    }

    int deltax = x1 - x0;
    int deltay = abs(y1 - y0);
    int error = -(deltax / 2);
    int y = y0;

    int y_step;
    if (y0 < y1)
        y_step = 1;
    else
        y_step = -1;

    for (int x = x0; x <= x1; x++) {
        if (is_steep)
            plot_pixel(y, x, line_color);
        else
            plot_pixel(x, y, line_color);

        error = error + deltay;

        if (error > 0) {
            y = y + y_step;
            error = error - deltax;
        }
    }
}

void draw_needle(int cx, int cy, int length, float theta, short int color) {
    int x1 = cx + (int)(length * sin(theta));
    int y1 = cy - (int)(length * cos(theta));   // minus because VGA y goes downward
    draw_line(cx, cy, x1, y1, color);
}

float freq_to_angle(float freq, float target_freq) {
    float error = freq - target_freq;   // + means sharp, - means flat
    float max_error = 15.0f;   // clamp range
    float max_angle = 1.6f;

    if (error > max_error) error = max_error;
    if (error < -max_error) error = -max_error;

    return (error / max_error) * max_angle;
}